-- ================================================================
--  VIEWS — se creo un reporte por tabla + vistas cruzadas

--  vw_entity_catalog
--  Reporte de entidades federativas registradas
CREATE OR REPLACE VIEW vw_entity_catalog AS
SELECT
    cve_entity,
    name                                    AS entity_name,
    IF(is_national, 'Nacional', 'Estatal') AS scope
FROM entity
ORDER BY cve_entity;
 
--  vw_year_catalog
CREATE OR REPLACE VIEW vw_year_catalog AS
SELECT
    y.year,
    COUNT(DISTINCT s.cve_entity) AS entities_with_suicide_data,
    COUNT(DISTINCT p.cve_entity) AS entities_with_population_data
FROM year y
LEFT JOIN suicide   s ON s.year = y.year
LEFT JOIN poblation p ON p.year = y.year
GROUP BY y.year
ORDER BY y.year;
 
--  vw_poblation_report
--  Reporte de población nacional por año con evolución
CREATE OR REPLACE VIEW vw_poblation_report AS
SELECT
    p.year,
    p.pop_men,
    p.pop_women,
    p.pop_total,
    ROUND(p.pop_men   / p.pop_total * 100, 2) AS pct_men,
    ROUND(p.pop_women / p.pop_total * 100, 2) AS pct_women,
    ROUND(
        p.pop_total / LAG(p.pop_total) OVER (ORDER BY p.year) * 100 - 100
    , 2)                                       AS yoy_growth_pct
FROM poblation p
WHERE p.cve_entity = 0
ORDER BY p.year;
 
--  vw_suicide_report
CREATE OR REPLACE VIEW vw_suicide_report AS
SELECT
    s.year,
    s.total                                                         AS suicides_total,
    s.male                                                          AS suicides_male,
    s.female                                                        AS suicides_female,
    s.unknown                                                       AS suicides_unknown,
    ROUND(s.rate_total,  4)                                         AS rate_per_100k,
    ROUND(s.rate_male,   4)                                         AS rate_male_per_100k,
    ROUND(s.rate_female, 4)                                         AS rate_female_per_100k,
    ROUND(s.rate_male / NULLIF(s.rate_female, 0), 2)               AS ratio_male_female,
    ROUND(
        s.total / LAG(s.total) OVER (ORDER BY s.year) * 100 - 100
    , 2)                                                            AS yoy_change_pct
FROM suicide s
WHERE s.cve_entity = 0
ORDER BY s.year;
 
--  vw_unemployment_report
CREATE OR REPLACE VIEW vw_unemployment_report AS
SELECT
    year,
    rate_total                              AS unemployment_total_pct,
    rate_male                               AS unemployment_male_pct,
    rate_female                             AS unemployment_female_pct,
    ROUND(rate_female - rate_male, 3)       AS gender_gap_pct,
    ROUND(rate_female / NULLIF(rate_male, 0), 3) AS ratio_female_male
FROM unemployment
WHERE cve_entity = 0
ORDER BY year;
 
--  vw_audit_log_report
--  Reporte de actividad de auditoría por tabla y operación
CREATE OR REPLACE VIEW vw_audit_log_report AS
SELECT
    table_name,
    operation,
    COUNT(*)                    AS total_events,
    MIN(log_timestamp)          AS first_event,
    MAX(log_timestamp)          AS last_event,
    COUNT(DISTINCT db_user)     AS distinct_users
FROM audit_log
GROUP BY table_name, operation
ORDER BY table_name, operation;
 
--  vw_national_summary
--  Vista maestra cruzada: suicidios + población + desempleo
CREATE OR REPLACE VIEW vw_national_summary AS
SELECT
    s.year,
    s.total                                         AS suicides_total,
    s.male                                          AS suicides_male,
    s.female                                        AS suicides_female,
    ROUND(s.rate_total,  4)                         AS suicide_rate_per_100k,
    ROUND(s.rate_male,   4)                         AS suicide_rate_male,
    ROUND(s.rate_female, 4)                         AS suicide_rate_female,
    p.pop_total,
    p.pop_men,
    p.pop_women,
    u.rate_total                                    AS unemployment_pct,
    u.rate_male                                     AS unemployment_male_pct,
    u.rate_female                                   AS unemployment_female_pct
FROM suicide      s
JOIN poblation    p ON p.year = s.year AND p.cve_entity = s.cve_entity
LEFT JOIN unemployment u ON u.year = s.year AND u.cve_entity = 0
WHERE s.cve_entity = 0
ORDER BY s.year;
 
--  vw_entity_summary
--  Todos los indicadores de suicidio por entidad y año
CREATE OR REPLACE VIEW vw_entity_summary AS
SELECT
    s.year,
    e.cve_entity,
    e.name                          AS entity_name,
    s.total                         AS suicides_total,
    s.male                          AS suicides_male,
    s.female                        AS suicides_female,
    ROUND(s.rate_total,  4)         AS rate_per_100k,
    ROUND(s.rate_male,   4)         AS rate_male_per_100k,
    ROUND(s.rate_female, 4)         AS rate_female_per_100k,
    p.pop_total,
    p.pop_men,
    p.pop_women
FROM suicide   s
JOIN entity    e ON e.cve_entity = s.cve_entity
JOIN poblation p ON p.year = s.year AND p.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
  AND s.cve_entity NOT IN (33, 99)
ORDER BY s.year, s.rate_total DESC;
 
--  vw_top5_by_year
--  Top 5 entidades con mayor tasa de suicidio por año
CREATE OR REPLACE VIEW vw_top5_by_year AS
SELECT year, ranking, entity_name, rate_per_100k, suicides_total
FROM (
    SELECT
        s.year,
        e.name                                              AS entity_name,
        s.total                                             AS suicides_total,
        ROUND(s.rate_total, 4)                              AS rate_per_100k,
        RANK() OVER (PARTITION BY s.year ORDER BY s.rate_total DESC) AS ranking
    FROM suicide   s
    JOIN entity    e ON e.cve_entity = s.cve_entity
    WHERE s.cve_entity NOT IN (0, 33, 99)
) ranked
WHERE ranking <= 5
ORDER BY year, ranking;
 
--  vw_gender_gap
--  Brecha de género en tasas de suicidio y desempleo (nacional)
CREATE OR REPLACE VIEW vw_gender_gap AS
SELECT
    s.year,
    ROUND(s.rate_male,                              4) AS suicide_rate_male,
    ROUND(s.rate_female,                            4) AS suicide_rate_female,
    ROUND(s.rate_male - s.rate_female,              4) AS suicide_gap,
    ROUND(s.rate_male / NULLIF(s.rate_female, 0),  2) AS suicide_ratio,
    u.rate_male                                        AS unemployment_male_pct,
    u.rate_female                                      AS unemployment_female_pct,
    ROUND(u.rate_female - u.rate_male,              3) AS unemployment_gap
FROM suicide      s
LEFT JOIN unemployment u ON u.year = s.year AND u.cve_entity = 0
WHERE s.cve_entity = 0
ORDER BY s.year;
 
--  vw_decade_summary
--  Promedios y totales agrupados por década
CREATE OR REPLACE VIEW vw_decade_summary AS
SELECT
    CONCAT(FLOOR(s.year / 10) * 10, 's')   AS decade,
    COUNT(*)                                AS years_counted,
    SUM(s.total)                            AS total_suicides,
    ROUND(AVG(s.rate_total), 4)             AS avg_suicide_rate,
    ROUND(MAX(s.rate_total), 4)             AS max_suicide_rate,
    ROUND(MIN(s.rate_total), 4)             AS min_suicide_rate,
    ROUND(AVG(u.rate_total), 3)             AS avg_unemployment_pct,
    ROUND(AVG(u.rate_male),  3)             AS avg_unemployment_male,
    ROUND(AVG(u.rate_female),3)             AS avg_unemployment_female
FROM suicide      s
LEFT JOIN unemployment u ON u.year = s.year AND u.cve_entity = 0
WHERE s.cve_entity = 0
GROUP BY decade
ORDER BY decade;